#!/usr/bin/env python3
"""Compare the player's KMS scanout with its software-rendered test frame."""
import argparse
import json
import socket
import time
from pathlib import Path
from PIL import Image
from build import ROOT, WORK
from test_boot import Guest
from test_faults import disk_copy


def screenshot(guest, name):
    # QEMU's human monitor is local-only; the image is generated by our guest.
    dest = guest.out / name
    monitor = socket.socket(socket.AF_UNIX)
    monitor.settimeout(5)
    monitor.connect(str(guest.out / 'monitor.sock'))
    def prompt():
        data = b''
        while b'(qemu)' not in data:
            chunk = monitor.recv(65536)
            if not chunk: raise RuntimeError('QEMU monitor closed')
            data += chunk
        return data
    prompt()
    monitor.sendall(('screendump /work/' + str(dest.relative_to(ROOT)) + '\n').encode())
    reply = prompt()
    monitor.close()
    if not dest.exists(): raise RuntimeError('screendump failed: ' + reply.decode(errors='replace'))
    return dest


parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--icount', action='store_true')
args = parser.parse_args()
guest = Guest(WORK / 'kernel-disk/uImage.gz', disk_copy(), args.icount)
try:
    guest.start()
    guest.seed_entropy()
    guest.check('KMS device exists', 'test -c /dev/dri/card0')
    guest.check('prepare generated KMS UI input', "mkdir -p /tmp/q2-drm-data; printf '[wifi]\\nenabled = false\\n[display]\\ntimezone = \"UTC\"\\n' > /tmp/q2-drm-data/config.toml; printf 'wait 1500\\nshot /tmp/q2-drm-frame.png\\nwait 30000\\n' > /tmp/q2-drm.script")
    for iteration in range(2):
        guest.check('start player on standard KMS', 'rm -f /tmp/q2-drm-frame.png; q2nd --drm-test --data /tmp/q2-drm-data --script /tmp/q2-drm.script > /tmp/q2-drm.log 2>&1 & echo $! > /tmp/q2-drm.pid')
        guest.check('KMS player renders', "timeout 40 sh -c 'until test -s /tmp/q2-drm-frame.png; do sleep 1; done'; test -s /tmp/q2-drm-frame.png && kill -0 \"$(cat /tmp/q2-drm.pid)\"", 60)
        guest.fetch('/tmp/q2-drm-frame.png', f'drm-software-{iteration}.png')
        time.sleep(.25)
        displayed = Image.open(screenshot(guest, f'drm-scanout-{iteration}.ppm')).convert('RGB')
        software = Image.open(guest.out / f'drm-software-{iteration}.png').convert('RGB').transpose(Image.Transpose.ROTATE_270)
        if displayed.size != (320, 375) or software.size != displayed.size:
            raise AssertionError('unexpected display dimensions')
        # Software screenshots mask physical panel corners; compare the full
        # central area where both images represent actual displayed pixels.
        box = (45, 45, 275, 330)
        if displayed.crop(box).tobytes() != software.crop(box).tobytes():
            raise AssertionError('KMS scanout differs from the rendered UI')
        guest.result['checks'].append('exact rotated UI pixels on KMS scanout')
        guest.check('backlight enabled', 'test "$(cat /sys/class/backlight/backlight/actual_brightness)" -gt 0')
        guest.check('stop KMS player cleanly', 'pid=$(cat /tmp/q2-drm.pid); kill -TERM "$pid"; wait "$pid"')
        guest.check('backlight off after close', 'test "$(cat /sys/class/backlight/backlight/actual_brightness)" = 0')
    guest.result['passed'] = True
except Exception as e:
    guest.result['error'] = str(e)
    raise
finally: guest.close()
